package com.quancrypt.qbank.account.infrastructure.config;

import java.nio.file.Path;
import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * Service settings. {@code certsDir} is the directory with the PEM files generated by reference-system/certs;
 * {@code jwt.ttlSeconds} is the access token lifetime.
 */
@ConfigurationProperties("qbank")
public record QbankProperties(String certsDir, Jwt jwt) {

    /** Access token settings. */
    public record Jwt(long ttlSeconds) {
    }

    public Path certsPath() {
        return Path.of(certsDir);
    }
}
